package com.oppzippy.openscq30.lite
 
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64
 
// The earbuds picture (120x144 PNG with a transparent background), embedded as text because the lite app
// has no image resources.
object EarbudsImage {
    private val pieces = arrayOf(
        "",
        "",
        "",
    )
 
    private var cached: Bitmap? = null
    private var tried = false
 
    // The decoded picture, or null if it could not be decoded (the caller then draws a simple replacement).
    fun bitmap(): Bitmap? {
        if (!tried) {
            tried = true
            try {
                val bytes = Base64.decode(pieces.joinToString(""), Base64.DEFAULT)
                cached = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
            } catch (_: Throwable) {
            }
        }
        return cached
    }
}
 



